steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        issues(filter: {
          title: {contains: \"login redirect\"},
          created_at: {before: \"2024-09-11\"},
          created_at: {after: \"2024-09-09\"}
        }) {
          nodes {
            id
            title
            createdAt
            team {
              name
            }
            user {
              name
            }
            assignee {
              name
            }
          }
        }
      }
    "
  }'
